// Board shell for the Alchitry Cu: the only hand-written logic around an
// HDLean solver.
//
// The 100 MHz oscillator drives the iCE40 PLL (`pll`, generated by icepll for
// the chosen frequency). The solver and its cycle counter run on the PLL clock.
// The UART reporter runs on the oscillator divided by two (50 MHz), so it never
// limits the solver's clock; it reads `done` through a two-flop synchronizer,
// and the answer and the cycle count, which no longer change once `done` is
// set, directly. Reset is held while the PLL is unlocked, while the reset button
// is pressed, and for 16 cycles after power-up, then released synchronously in
// each domain.
module euler_top (
  input wire clk,
  input wire rst_n,
  output wire usb_tx,
  output wire [7:0] led
);
  wire fclk;
  wire locked;
  pll pll_i (.clock_in(clk), .clock_out(fclk), .locked(locked));

  // solver domain
  reg [4:0] hold = 5'd0;
  reg [1:0] button = 2'b00;
  always @(posedge fclk) begin
    button <= {button[0], rst_n};
    if (!locked || !button[1]) hold <= 5'd0;
    else if (!hold[4]) hold <= hold + 5'd1;
  end
  wire rst = !hold[4];

  wire done;
  wire [`ANSWER_WIDTH-1:0] answer;
  wire [63:0] cycles;
  `SOLVER solver (.clk(fclk), .rst(rst), .i_0_start(1'b1), .o_0_done(done), .o_1_answer(answer));
  hd_0_cyclecount count (.clk(fclk), .rst(rst), .i_0_done(done), .o_0_cycles(cycles));

  // reporter domain
  reg slow = 1'b0;
  always @(posedge clk) slow <= !slow;
  reg [1:0] slow_rst = 2'b11;
  reg [1:0] slow_done = 2'b00;
  always @(posedge slow) begin
    slow_rst <= {slow_rst[0], rst};
    slow_done <= {slow_done[0], done};
  end
  hd_0_report report (.clk(slow), .rst(slow_rst[1]), .i_0_done(slow_done[1]),
    .i_1_answer({{(64-`ANSWER_WIDTH){1'b0}}, answer}), .i_2_cycles(cycles), .o_0_tx(usb_tx), .o_1_led(led));
endmodule
